public int rob(int[] nums) {
    return robFrom(nums, 0);
}

private int robFrom(int[] nums, int i) {
    if (i >= nums.length) {
        return 0;
    }
    int robThis = nums[i] + robFrom(nums, i + 2);
    int skipThis = robFrom(nums, i + 1);
    return Math.max(robThis, skipThis);
}

