public int rob(int[] nums) {
    int[] memo = new int[nums.length];
    Arrays.fill(memo, -1);
    return solve(nums, 0, memo);
}

private int solve(int[] nums, int i, int[] memo) {
    if (i >= nums.length) {
        return 0;
    }
    if (memo[i] != -1) {
        return memo[i];
    }
    int robThis = nums[i] + solve(nums, i + 2, memo);
    int skipThis = solve(nums, i + 1, memo);
    memo[i] = Math.max(robThis, skipThis);
    return memo[i];
}

code.python:
def rob(self, nums: list[int]) -> int:
    memo: dict[int, int] = {}

    def solve(i: int) -> int:
        if i >= len(nums):
            return 0
        if i in memo:
            return memo[i]
        rob_this = nums[i] + solve(i + 2)
        skip_this = solve(i + 1)
        memo[i] = max(rob_this, skip_this)
        return memo[i]

    return solve(0)

